#!/usr/bin/env node
/**
 * bundle-credentials.js — 빌드 시 OAuth 자격증명 암호화 번들 생성
 *
 * 사용법:
 *   node scripts/bundle-credentials.js
 *
 * 동작:
 *   1. electron-app/oauth-client.json 읽기
 *   2. AES-256-GCM으로 암호화
 *   3. 키를 3개 파트로 분할 (런타임에 XOR로 복원)
 *   4. src/main/services/bundled-credentials.js 생성
 *
 * 생성된 파일은 obfuscate.js에 의해 추가로 난독화된다.
 * 생성된 파일은 .gitignore에 추가되어 저장소에 포함되지 않는다.
 *
 * 주의: Client Secret은 Google의 "installed app" 정책상 완전한 비밀이 될 수 없다.
 *       PKCE + safeStorage 토큰 보호가 실질적인 보안 레이어다.
 */
'use strict';

const crypto = require('crypto');
const fs     = require('fs');
const path   = require('path');

const ROOT          = path.join(__dirname, '..');
const SRC_FILE      = path.join(ROOT, 'oauth-client.json');
const OUT_FILE      = path.join(ROOT, 'src', 'main', 'services', 'bundled-credentials.js');

function loadOAuthConfig() {
  if (!fs.existsSync(SRC_FILE)) {
    console.error('[bundle-credentials] oauth-client.json 파일이 없습니다:', SRC_FILE);
    process.exit(1);
  }
  const raw = JSON.parse(fs.readFileSync(SRC_FILE, 'utf8'));

  const installed = raw.installed || null;
  const web       = raw.web       || null;

  const clientId = (raw.clientId || raw.client_id ||
    (installed && installed.client_id) ||
    (web && web.client_id) || '').trim();

  const clientSecret = (raw.clientSecret || raw.client_secret ||
    (installed && installed.client_secret) ||
    (web && web.client_secret) || '').trim();

  if (!clientId || !clientSecret) {
    console.error('[bundle-credentials] clientId 또는 clientSecret이 비어 있습니다.');
    process.exit(1);
  }

  return { clientId, clientSecret };
}

function encryptCredentials(payload) {
  const plaintext = JSON.stringify(payload);

  // 256-bit 랜덤 키 생성
  const fullKey = crypto.randomBytes(32);

  // 키를 3개 파트로 XOR 분할: k1 ^ k2 ^ k3 = fullKey
  const k1 = crypto.randomBytes(32);
  const k2 = crypto.randomBytes(32);
  const k3 = Buffer.alloc(32);
  for (let i = 0; i < 32; i++) {
    k3[i] = fullKey[i] ^ k1[i] ^ k2[i];
  }

  const iv  = crypto.randomBytes(12);  // 96-bit IV for GCM
  const cipher = crypto.createCipheriv('aes-256-gcm', fullKey, iv);
  const enc = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()]);
  const tag = cipher.getAuthTag();

  return {
    enc: enc.toString('hex'),
    iv:  iv.toString('hex'),
    tag: tag.toString('hex'),
    k1:  k1.toString('hex'),
    k2:  k2.toString('hex'),
    k3:  k3.toString('hex'),
  };
}

function generateOutputFile(bundle) {
  // 변수명을 임의 문자열로 만들어 추출을 어렵게 함
  const names = Array.from({length: 6}, () => '_' + crypto.randomBytes(4).toString('hex'));
  const [nEnc, nIv, nTag, nK1, nK2, nK3] = names;

  return `'use strict';
/* AUTO-GENERATED by scripts/bundle-credentials.js — do not edit */
/* This file is encrypted and will be further obfuscated at build time */
(function(m){
  var ${nK1}='${bundle.k1}';
  var ${nK2}='${bundle.k2}';
  var ${nK3}='${bundle.k3}';
  var ${nIv}='${bundle.iv}';
  var ${nTag}='${bundle.tag}';
  var ${nEnc}='${bundle.enc}';
  m.exports={_e:${nEnc},_i:${nIv},_t:${nTag},_a:${nK1},_b:${nK2},_c:${nK3}};
})(module);
`;
}

function run() {
  console.log('[bundle-credentials] OAuth 자격증명 암호화 시작...');

  const payload = loadOAuthConfig();
  const bundle  = encryptCredentials(payload);
  const outDir  = path.dirname(OUT_FILE);

  if (!fs.existsSync(outDir)) fs.mkdirSync(outDir, { recursive: true });

  const content = generateOutputFile(bundle);
  fs.writeFileSync(OUT_FILE, content, 'utf8');

  console.log('[bundle-credentials] 생성 완료:', path.relative(ROOT, OUT_FILE));
  console.log('[bundle-credentials] (이 파일은 .gitignore에 포함되어야 합니다)');
}

run();
